/* From Uiverse.io by mi-series - Tags: simple, material design, neumorphism, purple, minimalist, form, brutalism */
.__UIV_SCOPE__ .container {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  text-align: center;
}

.__UIV_SCOPE__ .form_area {
  display: flex;
  justify-content: center;
  align-items: center;
  flex-direction: column;
  background-color: #EDDCD9;
  height: auto;
  width: auto;
  border: 2px solid #264143;
  border-radius: 20px;
  box-shadow: 3px 4px 0px 1px #E99F4C;
}

.__UIV_SCOPE__ .title {
  color: #264143;
  font-weight: 900;
  font-size: 1.5em;
  margin-top: 20px;
}

.__UIV_SCOPE__ .sub_title {
  font-weight: 600;
  margin: 5px 0;
}

.__UIV_SCOPE__ .form_group {
  display: flex;
  flex-direction: column;
  align-items: baseline;
  margin: 10px;
}

.__UIV_SCOPE__ .form_style {
  outline: none;
  border: 2px solid #264143;
  box-shadow: 3px 4px 0px 1px #E99F4C;
  width: 290px;
  padding: 12px 10px;
  border-radius: 4px;
  font-size: 15px;
}

.__UIV_SCOPE__ .form_style:focus, .__UIV_SCOPE__ .btn:focus {
  transform: translateY(4px);
  box-shadow: 1px 2px 0px 0px #E99F4C;
}

.__UIV_SCOPE__ .btn {
  padding: 15px;
  margin: 25px 0px;
  width: 290px;
  font-size: 15px;
  background: #DE5499;
  border-radius: 10px;
  font-weight: 800;
  box-shadow: 3px 3px 0px 0px #E99F4C;
}

.__UIV_SCOPE__ .btn:hover {
  opacity: .9;
}

.__UIV_SCOPE__ .link {
  font-weight: 800;
  color: #264143;
  padding: 5px;
}
